import java.util.*;
public class NQueens {
    List<List<String>> solutions = new ArrayList<>();
    public List<List<String>> solve(int n) {
        int[] queens = new int[n]; Arrays.fill(queens, -1);
        backtrack(queens, n, 0);
        return solutions;
    }
    void backtrack(int[] queens, int n, int row) {
        if (row == n) { solutions.add(buildBoard(queens, n)); return; }
        for (int col = 0; col < n; col++) {
            if (isSafe(queens, row, col)) {
                queens[row] = col;
                backtrack(queens, n, row + 1);
                queens[row] = -1; // backtrack
            }
        }
    }
    boolean isSafe(int[] queens, int row, int col) {
        for (int r = 0; r < row; r++) {
            if (queens[r] == col || Math.abs(queens[r] - col) == row - r) return false;
        }
        return true;
    }
    List<String> buildBoard(int[] queens, int n) {
        List<String> board = new ArrayList<>();
        for (int r = 0; r < n; r++) {
            char[] row = new char[n]; Arrays.fill(row, '.'); row[queens[r]] = 'Q';
            board.add(new String(row));
        }
        return board;
    }
    public static void main(String[] args) { System.out.println(new NQueens().solve(4).size()); }
}

